#include "stdafx.h"#include "SM_RemoteClient.h"#include <ConnectSM.h>#pragma comment( lib, "ConnectSM5xx.lib")#ifdef _MANAGED#pragma managed(push, off)#endifBOOL APIENTRY DllMain( HMODULE hModule,                       DWORD  ul_reason_for_call,                       LPVOID lpReserved					 ){  return TRUE;}#ifdef _MANAGED#pragma managed(pop)#endifstatic bool s_bConstructedMemory = false;extern "C" __declspec(dllexport) IBaseModel* CreateObject(LPCTSTR ObjName ){  if( !s_bConstructedMemory )  {    s_bConstructedMemory = true;    if( !pRegisterSMstructs )      LoadLibrary("SM5xxRegisterInRSU.dll");    if( pRegisterSMstructs )      pRegisterSMstructs();  }  return new KSM_RemoteClient( (char*)ObjName);}